<script setup lang="ts">
import { onMounted, ref } from 'vue'
import type { SessionUser, SubscriptionSummary, UsageSummary } from '@cyberboard/types'
import StatePanel from '@cyberboard/ui/components/StatePanel.vue'
import { getApiErrorMessage, portalApi } from '../api'
const loading=ref(true); const error=ref(''); const session=ref<SessionUser|null>(null); const subscription=ref<SubscriptionSummary|null>(null); const usage=ref<UsageSummary|null>(null)
async function load(){loading.value=true;error.value='';try{[session.value,subscription.value,usage.value]=await Promise.all([portalApi.getSession(),portalApi.getSubscription(),portalApi.getUsage()])}catch(cause){error.value=getApiErrorMessage(cause)}finally{loading.value=false}}
onMounted(load)
</script>
<template><div class="portal-heading"><div><p class="eyebrow">账户概览</p><h1>你好，{{session?.displayName ?? '用户'}}</h1><p>数据来自控制面 API，更新时间由服务端返回。</p></div><button class="button button--secondary" type="button" :disabled="loading" @click="load">{{loading?'加载中…':'刷新'}}</button></div><StatePanel v-if="loading" title="正在加载账户数据" description="正在读取 session、订阅和用量。"/><StatePanel v-else-if="error" title="账户数据加载失败" :description="error" action-label="重试" @action="load"/><template v-else><section class="portal-metrics"><article v-if="subscription"><span>当前套餐</span><strong>{{subscription.plan}}</strong><small>有效期至 {{subscription.expiresAt}}</small></article><StatePanel v-else title="暂无生效订阅" description="服务端尚未返回当前订阅。"/><article v-if="usage"><span>本周期用量</span><strong>{{(usage.usedBytes/1e9).toFixed(1)}} GB</strong><small>额度 {{(usage.quotaBytes/1e9).toFixed(1)}} GB</small></article><StatePanel v-else title="暂无用量数据" description="服务端尚未返回用量统计。"/><article v-if="usage"><span>预计周期用量</span><strong>{{(usage.projectedBytes/1e9).toFixed(1)}} GB</strong><small>统计周期 {{usage.periodStart}} 至 {{usage.periodEnd}}</small></article><StatePanel v-else title="暂无预测数据" description="服务端尚未返回用量预测。"/></section><section class="portal-grid"><div class="portal-panel"><h2>订阅快捷入口</h2><p>使用专属链接将配置导入支持 sing-box 的客户端。</p><RouterLink v-if="subscription" to="/portal/subscription" class="primary-button">查看订阅信息</RouterLink><StatePanel v-else title="暂无订阅入口" description="请先购买或等待订阅生效。"/></div><div class="portal-panel"><h2>服务状态</h2><div class="health-row"><span class="health-dot"/>控制面会话有效 <strong>{{session?.email}}</strong></div><p class="muted">登录状态由服务端 session 确认</p></div></section></template></template>
